import{_ as e,o as t,c as l,a5 as i}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"第1章 コンピュータと情報の表現","description":"","frontmatter":{"title":"第1章 コンピュータと情報の表現","study":{"source":"IT教本","status":"outline","summary":"ビット・整数・浮動小数点・文字の表現を学ぶ順序と演習を案内し、整数表現の辞典本文と観察例へつなぐ。","verification":"一次資料照合（2026-11-03）","section":"learning","format":"path","domain":"data","collection":"low-level","order":2}},"headers":[],"relativePath":"guide/low-level/computer-and-data.md","filePath":"guide/low-level/computer-and-data.md"}'),r={name:"guide/low-level/computer-and-data.md"};function o(n,a,s,d,c,h){return t(),l("div",null,[...a[0]||(a[0]=[i(`<div id="第1章-コンピュータとは何か-──-情報の表現" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第1章-コンピュータと情報の表現" tabindex="-1">第1章 コンピュータと情報の表現 <a class="header-anchor" href="#第1章-コンピュータと情報の表現" aria-label="Permalink to &quot;第1章 コンピュータと情報の表現&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>ビット列から整数・浮動小数点・文字・ファイル表現へ進むための<strong>学習計画・概要</strong>です。表現の違いを小さなプログラムで観察する題材を選びます。Unicodeやファイル形式などの専用の辞典本文は、まだ整備していません。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/data/integer-bits-and-bytes.html">ビット・バイト・整数表現</a>で、整数の幅、符号、型変換、バイト順を調べられます。</li><li><a href="/study/practice/data/integer-byte-observation.html">整数とバイト列の観察</a>で、小さなC++プログラムによる確認へ進めます。</li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウト・エンディアン</a>では、構造体の整列・パディングと、バイト順を区別します。</li><li><a href="/study/design/case-studies/save-data.html">セーブデータのケーススタディ</a>では、表現の知識を保存形式の設計へつなげられます。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>すべてのゲームデータ ── 座標、HP、テクスチャ、サウンド、セーブデータ ── は 最終的に<strong>ビット列</strong>である。「floatの精度でキャラがガタつく」「色が変」 「セーブデータが壊れた」といった実務のバグは、ビットレベルの表現を 知らないと原因にたどり着けない。ここは全20章の土台の土台。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>任意の整数を2進数・16進数で読み書きできる</li><li>2の補数による表現と、符号付き・符号なしの間の値の変換を区別できる</li><li>IEEE 754浮動小数点の構造(符号・指数・仮数)を説明できる</li><li>「floatで0.1が正確に表せない」「大きな座標で精度が落ちる」理由が分かる</li><li>文字コード(ASCII/UTF-8)とエンディアンを説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>なし。ここが出発点。</p><p>整数のC++例は<strong>C++20</strong>を対象にします。C++の1バイトは<code>sizeof</code>が数える単位で、ビット数は<code>CHAR_BIT</code>で確認します。以下の32ビット整数の観察例では、<strong><code>CHAR_BIT == 8</code>で<code>std::uint32_t</code>が提供される環境</strong>を前提にします。<code>int</code>が常に32ビットとは限らず、固定幅型もすべての処理系で提供されるわけではありません。<a href="https://timsong-cpp.github.io/cppwp/n4861/intro.memory" target="_blank" rel="noreferrer">C++20草案のメモリモデル</a>と<a href="https://timsong-cpp.github.io/cppwp/n4861/cstdint.syn" target="_blank" rel="noreferrer">固定幅整数型</a>を参照してください。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>2進数・16進数</strong><ul><li>ビット、バイト、ワード。なぜ16進数を使うか(4bit=1桁でビットと相性が良い)</li><li>ビット演算: AND/OR/XOR/NOT、シフト。フラグ管理 <code>flags |= JUMPING</code></li></ul></li><li><strong>整数の表現</strong><ul><li>符号なし整数と2の補数。C++20の符号付き整数では、対応する符号なし整数と2の補数の関係で値を表す。これは古いC/C++のすべてにそのまま当てはまる前提ではない</li><li>演算が幅Nの符号なし整数型で行われる場合、結果は2^Nを法とする。符号付き整数の算術で結果がその型の表現範囲を超えると未定義動作になる。<a href="https://timsong-cpp.github.io/cppwp/n4861/basic.fundamental" target="_blank" rel="noreferrer">C++20草案の整数型</a>を参照</li><li>ただし、小さい符号なし整数型は演算前に<code>int</code>などへ<strong>整数昇格</strong>する。8ビット型の変数同士でも、加算が8ビット幅で行われるとは限らない。格納先への変換と、演算に使われる型を分ける。<a href="https://timsong-cpp.github.io/cppwp/n4861/conv.prom" target="_blank" rel="noreferrer">整数昇格</a>と<a href="https://timsong-cpp.github.io/cppwp/n4861/expr.arith.conv" target="_blank" rel="noreferrer">通常の算術型変換</a>を参照</li><li>例えば<code>(int)-1 == (unsigned)0xFFFFFFFF</code>は、<code>unsigned int</code>が32ビットの環境では真になるが、比較時の値の変換による結果であり、メモリ表現を調べる式ではない。幅が異なれば結果も変わり得る。2の補数の証明としては使わない。<a href="https://timsong-cpp.github.io/cppwp/n4861/conv.integral" target="_blank" rel="noreferrer">整数変換</a>を参照</li><li>固定小数点数(昔のゲーム機や、演算の再現性を設計したい場面で使う)。 これを選ぶだけで決定性が保証されるわけではなく、丸め・溢れ・処理順も揃える</li></ul></li><li><strong>浮動小数点 (IEEE 754)</strong><ul><li>本章では一般的なIEEE 754 binary32のfloatを例にする: 符号1 + 指数8 + 格納する仮数部23bit。C/C++の型名だけでこの形式が保証されるわけではない</li><li>精度の偏り: 0付近は細かく、大きくなるほど粗い → <strong>オープンワールドで原点から離れるとアニメがガタつく理由</strong> (対策: カメラ相対レンダリング、ワールドオリジンシフト)</li><li>特殊値: NaN, Inf, -0。NaNは伝染する(<code>NaN != NaN</code> に注意)</li><li>binary64の例では <code>0.1 + 0.2 != 0.3</code> となる。比較方法は用途で選ぶ。 近似一致は値の規模に応じた相対許容誤差と、0付近の絶対許容誤差を検討する。 型のepsilonを全ての値へ固定で当てはめない。厳密一致が必要な場合やNaN/Infも別途扱う</li></ul></li><li><strong>文字と色の表現</strong><ul><li>ASCII、Unicode、UTF-8/UTF-16。OSやエンジンの名前だけで文字列の形式を決めず、使用するAPIやファイル形式の仕様を確認する</li><li>色: RGBA8888、リニア色空間とsRGB(第12章で再訪)</li></ul></li><li><strong>エンディアン</strong><ul><li>リトル/ビッグエンディアンは、複数バイトの値をアドレス順に並べるときのバイト順。バイト内のビットを反転する話ではない</li><li>実行環境のバイト順と、アセット・セーブデータ・通信プロトコルが定めるバイト順を区別する。ARMやGPUを一括して同じ順序と決めつけない。詳しくは<a href="/study/data/integer-bits-and-bytes.html">整数表現の本文</a>へ</li></ul></li><li><strong>ノイマン型アーキテクチャの概観</strong><ul><li>「命令もデータもメモリに保持し、CPUが命令を読み出して処理する」という説明モデル</li><li>現代CPUが内部でも常に1命令ずつ順番に完了させる、という意味ではない</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>ビット列の意味は形式と解釈で決まる。</strong> 同じ32ビットでも、整数、binary32の浮動小数点、色など、選んだ形式によって意味が変わる。値を変換するキャストと、表現のバイトを調べる操作は別であり、任意の型のポインタで読み替えてよいわけではない。</li><li><strong>2の補数</strong>: 加算の仕組みを使って減算も扱える整数表現</li><li><strong>浮動小数点には表現と演算の丸めがある</strong>: 許容できる誤差と、その扱いを設計する</li><li><strong>精度は相対的</strong>: binary32の精度は10進数で約7桁が目安だが、どの10進数でも7桁まで正確に保持できるという意味ではない</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>ビットフラグでの状態管理</td><td>ビット演算</td></tr><tr><td>座標が大きいと物理・アニメが暴れる</td><td>floatの相対精度</td></tr><tr><td>リプレイ再現が環境でズレる</td><td>演算順・コンパイラ設定・乱数・更新順の再現性。固定小数点も選択肢</td></tr><tr><td>セーブデータ/アセットのバイナリ解析</td><td>16進ダンプ、エンディアン</td></tr><tr><td>日本語ファイル名/テキストの文字化け</td><td>UTF-8/UTF-16</td></tr><tr><td>HDR対応で色が変わった</td><td>色の数値表現・色空間</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>電卓を使わず 0xDEADBEEF を10進・2進に変換せよ。</li><li><code>float</code>がbinary32で最近接・偶数丸めの環境で、<code>float f = 16777216.0f; f += 1.0f;</code> の結果を観察せよ。値が増えない理由を、有効精度24ビット（通常の正規化数では先頭の1を含む）から説明せよ。</li><li><code>CHAR_BIT == 8</code>、<code>sizeof(float) == sizeof(std::uint32_t) == 4</code>、<code>float</code>がbinary32の環境で、<code>memcpy</code>により<code>float</code>の表現を<code>std::uint32_t</code>へ写し、符号・指数・仮数を分解せよ（1.0f、-2.5f、0.1f）。整数と浮動小数点のバイト順が対応することも確認する。サイズが合わない状態でコピーしない。</li><li>プレイヤー状態(ジャンプ中/無敵/ダッシュ中...)を1つの<code>std::uint32_t</code>の ビットフラグで管理する関数群(set/clear/test)を書け。</li><li>バイナリエディタ(VSの「バイナリで開く」やHxD)でBMPファイルを開き、 ヘッダの幅・高さをリトルエンディアンで読み取れ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『プログラムはなぜ動くのか』矢沢久雄 ── 最初の1冊として最適</li><li>『コンピュータシステムの理論と実装(Nand2Tetris)』── 第2章と併読</li><li>『Land of Lisp』…は不要。寄り道しないこと</li><li>(英語余裕があれば)&quot;Computer Systems: A Programmer&#39;s Perspective (CS:APP)&quot; 第2章 ── 情報表現の決定版。邦訳『コンピュータ・システム』</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><a href="https://float.exposed" target="_blank" rel="noreferrer">float.exposed</a> / [IEEE754 Visualizer] ── 浮動小数を ビット単位でいじれるWebツール(OSSではないが実験場として最高)</li><li>stb_image (GitHub: nothings/stb) ── 画像=バイト列であることが分かる 1ファイルCライブラリ。読むのは第5章以降でよいが存在を知っておく</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Ben Eater &quot;How do computers read binary?&quot; ほか (YouTube, 英語・字幕可)</li><li>「浮動小数点数」で検索して出るCEDECの数値精度系講演</li><li>Computerphile &quot;Floating Point Numbers&quot;</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>UE5 <code>Engine/Source/Runtime/Core/Public/Math/Float16.h</code> ── 半精度floatの ビット操作の実例(第17章で戻ってきたときに読めるようになっている)</li><li>Quake III <code>q_math.c</code> の高速逆平方根(0x5f3759df)── 「ビットの再解釈」の 最も有名な実例。今は雰囲気だけ眺め、第4章後に再読</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>なぜコンピュータは2進数なのか?(電気的な理由で)</li><li>2の補数で値を表す8ビット符号付き整数の範囲が -128〜127 と非対称なのはなぜ?</li><li>floatの <code>0.1f</code> が正確に0.1でないのはなぜ? どう比較すべき?</li><li>座標(100000.0f, 0, 0)付近でキャラが小刻みに震える。原因と対策を述べよ。</li><li>8ビットの1バイトが0x41のとき、符号なし整数として・ASCII文字として何を表すか?</li><li><code>CHAR_BIT == 8</code>のリトルエンディアン環境で、<code>std::uint32_t x = 0x12345678;</code> の4バイトは、アドレスの小さい側からどう並ぶか?</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ボタン → OS → ゲームループ → エンジン → GPU → 画面</span></span>
<span class="line"><span>                  │            │        │</span></span>
<span class="line"><span>                  ▼            ▼        ▼</span></span>
<span class="line"><span>           HP,座標,フラグ   Transform  頂点データ,色</span></span>
<span class="line"><span>           = int/float     = float×16  = float/半精度/sRGB</span></span>
<span class="line"><span>           ─────────── すべて「ビット列+解釈」───────────</span></span>
<span class="line"><span>     セーブデータ・アセットファイル・ネットパケットも全部バイト列</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://timsong-cpp.github.io/cppwp/n4861/basic.fundamental" target="_blank" rel="noreferrer">C++20草案 N4861: 基本型と整数表現</a></li><li><a href="https://timsong-cpp.github.io/cppwp/n4861/conv.prom" target="_blank" rel="noreferrer">C++20草案 N4861: 整数昇格</a>・<a href="https://timsong-cpp.github.io/cppwp/n4861/conv.integral" target="_blank" rel="noreferrer">整数変換</a>・<a href="https://timsong-cpp.github.io/cppwp/n4861/expr.arith.conv" target="_blank" rel="noreferrer">通常の算術型変換</a></li><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li><li><a href="https://learn.microsoft.com/en-us/dotnet/api/system.single.equals?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: Single.Equals — comparison tolerance</a></li><li><a href="https://learn.microsoft.com/en-us/cpp/build/reference/fp-specify-floating-point-behavior?view=msvc-170" target="_blank" rel="noreferrer">MSVC: /fp floating-point behavior</a></li><li><a href="https://box2d.org/posts/2024/08/determinism/" target="_blank" rel="noreferrer">Box2D: Determinism</a></li></ul><p>整数に関するC++20の説明を2026-11-03に一次資料と照合しました。N4861へのリンクは規格草案本文のHTML表示です。このページの演習は学習題材であり、今回すべての環境で実行したものではありません。</p>`,37)])])}const f=e(r,[["render",o]]);export{u as __pageData,f as default};
